(function(root){
 'use strict';
 root.MOBTWIG_COMMUNITY_UI={create(ctx){
  const C=root.MOBTWIG_COMMUNITY,P=C.POLICY,esc=ctx.escape;
  const store=C.createStore({getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)},ctx.getUser,ctx.books);
  let session=ctx.getUser()?.id||null,editor=null,homeTab='work',workQuery='',postQuery='',postHead='전체',activeBoard='',commentDrafts=new Map(),pendingUpload=null;
  const $=selector=>document.querySelector(selector),attr=(key,value)=>`data-${key}="${esc(value)}"`;
  const cb=(action,label,attrs='',className='secondary')=>`<button type="button" data-community-action="${action}" ${attrs} class="${className}">${label}</button>`;
  const nav=(label,route,cls='text-link')=>ctx.button('nav',esc(label),`data-route="${esc(route)}"`,cls);
  const boardRoute=id=>'community-board/'+encodeURIComponent(id),postRoute=id=>'community-post/'+encodeURIComponent(id);
  const date=value=>new Date(value).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric'});
  const byBoard=id=>store.boards().find(board=>board.id===id),byWork=id=>store.works().find(work=>work.id===id);
  const scopeLabel=(workId,scope)=>scope?`${scope}${byWork(workId)?.type==='book'?'장':'화'}까지`:'스포일러 없음';
  const notice=()=>'<p class="comm-demo-note">가상 커뮤니티 · 실제 차단 효과와 운영 정책은 아직 연결되지 않았어요.</p>';
  const shell=body=>ctx.shell(body,'community','커뮤니티');
  function syncSession(){const current=ctx.getUser()?.id||null;if(current!==session){session=current;editor=null;pendingUpload=null;commentDrafts.clear();activeBoard='';postQuery='';postHead='전체';}}
  function error(error){const message=error instanceof Error?error.message:String(error),node=$('#community-form-error')||$('#community-comment-error')||$('#community-error');if(node)node.textContent=message;else ctx.toast(message);}
  function boardCard(board){return cb('board',`<span class="comm-board-icon" aria-hidden="true">${ctx.icon(board.type==='work'?'book':'comment')}</span><span><strong>${esc(board.title)}</strong><small>${esc(board.subtitle||'')}</small></span>${ctx.icon('chevron')}`,attr('board',board.id),'comm-board-card');}
  function imageSrc(image){return image.kind==='fixture'?C.FIXTURES[image.fixture].src:image.dataUrl;}
  function imageAlt(image){return image.kind==='fixture'?C.FIXTURES[image.fixture].name:image.name||'본문 첨부 이미지';}
  const emoteImage=(id,cls='')=>`<img class="comm-emote ${cls}" src="${C.EMOTES[id].src}" width="96" height="96" alt="${esc(C.EMOTES[id].name)} 이미지 이모티콘">`;
  function workResults(){const query=workQuery.trim().toLocaleLowerCase(),type=ctx.getWorkType();const rows=store.boards().filter(b=>b.type==='work'&&byWork(b.workId)?.type===type&&(!query||[b.title,b.subtitle].some(t=>t.toLocaleLowerCase().includes(query))));return `<p class="result-count">${rows.length}개 작품 게시판</p><div class="comm-board-grid">${rows.map(boardCard).join('')||'<div class="comm-empty">일치하는 작품 게시판이 없어요.<br>다른 작품명이나 작가명으로 찾아보세요.</div>'}</div>`;}
  function home(){const favorites=store.profile().favorites.map(byBoard).filter(Boolean);return shell(`${ctx.heading('이야기 밖의 이야기','같은 작품, 다른 시선. 함께 이야기해 보세요.','COMMUNITY')}<section class="comm-promotion-callout"><div><span class="eyebrow">INTRODUCE YOUR STORY</span><h2>새로운 이야기를 소개해요</h2><p>작품 토론과 분리된 홍보 게시판</p></div>${cb('board','작품 홍보 '+ctx.icon('arrow'),attr('board','promotion'),'primary')}</section><section class="section"><div class="section-header"><h2>즐겨찾는 게시판</h2><small>작품 찜과 별도</small></div><div class="comm-board-grid">${favorites.map(boardCard).join('')||'<p class="comm-empty">자주 찾는 게시판을 즐겨찾기에 추가해 보세요.</p>'}</div></section><section class="section"><div class="comm-tabs" role="group" aria-label="게시판 종류">${cb('home-tab','작품별 게시판',`data-tab="work" aria-pressed="${homeTab==='work'}"`,homeTab==='work'?'selected':'')}${cb('home-tab','주제별 게시판',`data-tab="topic" aria-pressed="${homeTab==='topic'}"`,homeTab==='topic'?'selected':'')}</div>${homeTab==='work'?`${nav('작품명·작가명으로 게시판 찾기','community-workboards','comm-find-link')}<div class="comm-board-grid">${store.boards().filter(b=>b.type==='work'&&byWork(b.workId)?.type===ctx.getWorkType()).slice(0,4).map(boardCard).join('')||'<p class="comm-empty">등록된 작품 게시판이 없어요.</p>'}</div>`:`<div class="comm-board-grid">${store.boards().filter(b=>b.type==='topic').map(boardCard).join('')}</div>`}</section>${notice()}`);}
  function workBoards(){return shell(`${ctx.backHead('작품 게시판 찾기','community')}${ctx.heading('어떤 이야기를 찾으세요?','작품명 또는 작가명으로 게시판을 찾아보세요.','FIND YOUR BOARD')}<label class="comm-search"><span class="sr-only">작품명 또는 작가명</span><input id="community-work-query" type="search" value="${esc(workQuery)}" placeholder="작품명, 작가명" aria-label="작품명 또는 작가명">${ctx.icon('search')}</label><div id="community-work-results">${workResults()}</div>${notice()}`);}
  function postRow(post){if(post.locked)return cb('post',`<div class="comm-post-info"><span class="comm-scope">${esc(scopeLabel(post.linkedWorkId,post.scope))} · 확인 전 가림</span><strong>스포일러가 포함된 게시글</strong><p>제목·미리보기·대표이미지는 확인 후 표시됩니다.</p><small>${esc(post.name)} · ${date(post.createdAt)} · 댓글 ${post.commentCount}</small></div><span class="comm-lock-thumb" aria-label="스포일러 이미지 가림">${ctx.icon('lock')}</span>`,attr('post',post.id),'comm-post-row comm-post-locked');const representative=post.images.find(image=>image.id===post.representativeId);return cb('post',`<div class="comm-post-info"><span class="comm-head">${esc(post.head)}</span><strong>${esc(post.title)}</strong><p>${esc(post.body)}</p><small>${esc(post.name)} · ${date(post.createdAt)} · 댓글 ${post.commentCount}${post.scope?' · '+esc(scopeLabel(post.linkedWorkId,post.scope)):''}</small></div>${representative?`<img class="comm-thumbnail" src="${esc(imageSrc(representative))}" width="72" height="72" alt="${esc(post.title)} 대표이미지">`:''}`,attr('post',post.id),'comm-post-row');}
  function boardResults(boardId){const rows=store.list(boardId,postQuery,postHead);return `<p class="result-count">${rows.length}개 게시글</p><div class="comm-post-list">${rows.map(postRow).join('')||'<div class="comm-empty">아직 표시할 글이 없어요.<br>검색 조건을 바꾸거나 첫 글을 남겨 보세요.</div>'}</div>`;}
  function boardPage(id){const board=byBoard(id);if(!board)throw Error('이 게시판을 찾을 수 없습니다.');if(activeBoard!==id){activeBoard=id;postQuery='';postHead='전체';}const favorite=store.profile().favorites.includes(id);return shell(`${ctx.backHead(board.type==='promotion'?'작품 홍보':'게시판','community')}<section class="comm-board-hero"><span class="eyebrow">${board.type==='work'?'WORK BOARD':board.type==='promotion'?'PROMOTION ONLY':'TOPIC BOARD'}</span><div class="comm-title-row"><h1>${esc(board.title)}</h1>${cb('favorite',ctx.icon(favorite?'heart':'plus'),`${attr('board',id)} aria-label="게시판 즐겨찾기${favorite?' 해제':''}" aria-pressed="${favorite}"`,'icon-btn')}</div><p>${esc(board.subtitle)}</p>${board.workId?`<div class="inline-actions">${nav('작품 상세','detail/'+board.workId)}${nav('기존 작품 리뷰','detail/'+board.workId+'?tab=reviews')}</div>`:board.type==='promotion'?'<p class="comm-board-help">연결 작품과 소개를 남기는 별도 공간입니다. 작품 토론은 작품별 게시판을 이용해 주세요.</p>':''}</section><div class="comm-board-toolbar"><div class="chips" role="group" aria-label="게시글 말머리">${['전체',...board.heads].map(head=>cb('head',esc(head),`${attr('board',id)} data-head="${esc(head)}" aria-pressed="${head===postHead}"`,'chip '+(head===postHead?'selected':''))).join('')}</div>${cb('compose','글쓰기',attr('board',id),'primary')}</div><label class="comm-search"><span class="sr-only">게시판 안 검색</span><input id="community-post-query" value="${esc(postQuery)}" type="search" placeholder="열람 가능한 제목·본문 검색" aria-label="게시판 안 검색">${ctx.icon('search')}</label><div id="community-board-results">${boardResults(id)}</div>${notice()}<p id="community-error" class="form-error" role="alert"></p>`);}
  function spoilerGate(kind,item,workId){return `<section class="comm-spoiler-gate"><span class="comm-gate-icon">${ctx.icon('lock')}</span><h2>스포일러가 포함되어 있어요</h2><p>${esc(byWork(workId)?.title||'연결 작품')} · ${esc(scopeLabel(workId,item.scope))} 내용을 확인한 뒤 열어 주세요.</p><p class="section-note">설정집 개방과 별개로 이 ${kind==='post'?'게시글':'댓글'}만 확인합니다.</p>${cb('ask-reveal','내용 확인 후 열기',`data-kind="${kind}" data-item="${esc(item.id)}" data-work="${esc(workId)}" data-scope="${item.scope}"`,'primary')}</section>`;}
  function commentState(post){const owner=ctx.getUser()?.id||'guest',key=owner+':'+post.id;if(!commentDrafts.has(key))commentDrafts.set(key,{body:'',emotes:[],scope:0,ownerId:owner});return commentDrafts.get(key);}
  function scopeOptions(workId,value){const work=byWork(workId);return `<option value="0" ${value===0?'selected':''}>스포일러 없음</option>${work?Array.from({length:work.chapters},(_,i)=>`<option value="${i+1}" ${value===i+1?'selected':''}>${i+1}${work.type==='book'?'장':'화'}까지 내용 포함</option>`).join(''):''}`;}
  function postPage(id){const post=store.post(id),board=byBoard(post.boardId);if(!board)throw Error('게시판을 찾을 수 없습니다.');if(post.locked)return shell(`${ctx.backHead('게시글',boardRoute(board.id))}${spoilerGate('post',post,post.linkedWorkId)}<p id="community-error" class="form-error" role="alert"></p>`);const comments=store.comments(id),draft=commentState(post);return shell(`${ctx.backHead(board.title,boardRoute(board.id))}<article class="comm-article"><span class="comm-head">${esc(post.head)}</span><h1>${esc(post.title)}</h1><div class="comm-byline"><span class="avatar" aria-hidden="true">${esc(Array.from(post.name)[0]||'독')}</span><strong>${esc(post.name)}</strong><small>${date(post.createdAt)}</small></div>${post.scope?`<p class="comm-scope">확인한 범위 · ${esc(scopeLabel(post.linkedWorkId,post.scope))}</p>`:''}${board.type==='promotion'&&post.linkedWorkId?`<aside class="comm-linked-work"><strong>${esc(byWork(post.linkedWorkId)?.title||'작품')}</strong>${nav('소개한 작품 보기','detail/'+post.linkedWorkId)}</aside>`:''}<p class="comm-body">${esc(post.body)}</p><div class="comm-body-images">${post.images.map(image=>`<figure><img src="${esc(imageSrc(image))}" alt="${esc(imageAlt(image))}"></figure>`).join('')}</div><div class="comm-emotes">${post.emotes.map(id=>emoteImage(id)).join('')}</div></article><section class="section comm-comments"><h2>댓글 ${comments.length}</h2><div class="comm-comment-list">${comments.map(comment=>comment.locked?`<article class="comm-comment" data-comment="${esc(comment.id)}"><strong>${esc(comment.name)}</strong>${spoilerGate('comment',comment,post.linkedWorkId)}</article>`:`<article class="comm-comment" data-comment="${esc(comment.id)}"><div class="comm-comment-meta"><strong>${esc(comment.name)}</strong><small>${date(comment.createdAt)}</small></div>${comment.scope?`<small class="comm-scope">${esc(scopeLabel(post.linkedWorkId,comment.scope))}</small>`:''}<p class="comm-body">${esc(comment.body)}</p><div class="comm-emotes">${comment.emotes.map(id=>emoteImage(id)).join('')}</div></article>`).join('')||'<p class="comm-empty">첫 댓글을 남겨 보세요.</p>'}</div>${ctx.getUser()?`<form data-community-form="comment" data-post="${esc(id)}" data-owner="${esc(ctx.getUser().id)}" class="comm-comment-form"><label class="field"><span>댓글</span><textarea id="community-comment-body" name="body" rows="3" maxlength="${P.commentChars}" placeholder="함께 나누고 싶은 이야기를 적어 주세요.">${esc(draft.body)}</textarea></label><div class="comm-selected-emotes">${draft.emotes.map((id,index)=>`<span>${emoteImage(id)}${cb('remove-emote','×',`data-destination="comment" data-index="${index}" aria-label="댓글 이모티콘 삭제"`,'comm-remove')}</span>`).join('')}</div><div class="comm-comment-tools">${cb('emotes',ctx.icon('spark')+' 이미지 이모티콘',`data-destination="comment" aria-label="댓글 이미지 이모티콘 선택"`,'secondary')}<label>범위 <select id="community-comment-scope" aria-label="댓글 스포일러 범위">${scopeOptions(post.linkedWorkId,draft.scope)}</select></label></div><p class="section-note">일반 이미지는 댓글에 첨부할 수 없어요. 입력한 이미지 주소도 자동으로 표시하지 않습니다.</p><p id="community-comment-error" role="alert" class="form-error"></p><button type="submit" class="primary">댓글 등록</button></form>`:nav('로그인하고 댓글 쓰기','login','primary')}</section>${notice()}`);}
  function readEditor(){if(!editor)return;const form=$('[data-community-form="post"]');if(!form)return;editor.title=form.elements.title.value;editor.body=form.elements.body.value;editor.head=form.elements.head.value;editor.scope=Number(form.elements.scope.value);editor.linkedWorkId=form.elements.linkedWork.value;}
  function attachmentTray(){return editor.images.map(image=>`<article class="comm-attachment" data-image="${esc(image.id)}"><img src="${esc(imageSrc(image))}" width="64" height="64" alt="${esc(imageAlt(image))}"><div><span>${esc(imageAlt(image))}</span><div>${cb('representative',editor.representativeId===image.id?'대표이미지':'대표로 선택',`${attr('image',image.id)} aria-pressed="${editor.representativeId===image.id}"`,'text-link')}${cb('remove-image','삭제',attr('image',image.id),'text-link danger')}</div></div></article>`).join('');}
  function composer(boardId){if(!ctx.getUser())return shell(`${ctx.backHead('글쓰기','community')}<div class="comm-empty">로그인 후 글과 초안을 작성할 수 있어요.${nav('로그인','login','primary')}</div>`);if(!editor){editor=store.draft()||store.newDraft(boardId);if(!editor.linkedWorkId&&byBoard(editor.boardId)?.type==='promotion')editor.linkedWorkId=store.works()[0]?.id||'';}const board=byBoard(editor.boardId);return shell(`${ctx.backHead('글쓰기',boardRoute(editor.boardId))}<div class="comm-compose-heading"><h1>새 이야기 남기기</h1><p>임시저장한 초안은 이 계정에서 이어 쓸 수 있어요.</p></div><form data-community-form="post" data-owner="${esc(editor.ownerId)}" class="comm-compose-form"><label class="field"><span>게시판</span><select id="community-compose-board" name="boardId" aria-label="글 게시판">${store.boards().map(b=>`<option value="${esc(b.id)}" ${b.id===editor.boardId?'selected':''}>${esc(b.type==='work'?'작품 · '+b.title:b.title)}</option>`).join('')}</select></label><div class="comm-compose-options"><label class="field"><span>말머리</span><select name="head" aria-label="글 말머리">${board.heads.map(head=>`<option ${head===editor.head?'selected':''}>${esc(head)}</option>`).join('')}</select></label><label class="field"><span>${board.type==='promotion'?'홍보할 작품':'스포일러 기준 작품'}</span><select id="community-linked-work" name="linkedWork" aria-label="연결 작품" ${board.type==='work'?'disabled':''}><option value="">연결 없음</option>${store.works().map(w=>`<option value="${esc(w.id)}" ${editor.linkedWorkId===w.id?'selected':''}>${esc(w.title)}</option>`).join('')}</select></label></div><label class="field"><span>제목</span><input name="title" aria-label="게시글 제목" value="${esc(editor.title)}" maxlength="${P.titleChars}" required placeholder="이야기의 제목을 적어 주세요."></label><label class="field"><span>본문</span><textarea name="body" aria-label="게시글 본문" rows="9" maxlength="${P.bodyChars}" required placeholder="감상이나 질문, 나누고 싶은 이야기를 적어 주세요.">${esc(editor.body)}</textarea></label><div class="comm-editor-tools"><label class="secondary comm-file-button">${ctx.icon('plus')} 본문 이미지<input id="community-file" type="file" accept="image/png,image/jpeg,image/webp" multiple aria-label="본문 일반 이미지 첨부"></label>${cb('emotes',ctx.icon('spark')+' 이미지 이모티콘','data-destination="post" aria-label="본문 이미지 이모티콘 선택"','secondary')}</div><p class="section-note">시연 기준: PNG·JPEG·WebP 3장, 원본 각 2MB 이하. 이미지는 본문 끝에 표시합니다.</p><div class="comm-attachment-list">${attachmentTray()}</div><div class="comm-selected-emotes">${editor.emotes.map((id,index)=>`<span>${emoteImage(id)}${cb('remove-emote','×',`data-destination="post" data-index="${index}" aria-label="본문 이모티콘 삭제"`,'comm-remove')}</span>`).join('')}</div><label class="field"><span>스포일러 범위</span><select name="scope" aria-label="게시글 스포일러 범위">${scopeOptions(editor.linkedWorkId,editor.scope)}</select></label><p class="section-note">범위를 지정하면 제목·미리보기·대표이미지·본문을 확인 전까지 가립니다. 설정집 개방과는 별개입니다.</p><p id="community-form-error" class="form-error" role="alert"></p><p id="community-save-status" role="status" class="section-note"></p><div class="comm-publish-actions">${cb('save-draft','임시저장','','secondary')}<button type="submit" class="primary">게시하기</button></div></form>${notice()}`);}
  function picker(destination){readEditor();const target=destination==='post'?editor:commentState(store.post(decodeURIComponent(ctx.route().parts[1]||'')));if(!target)throw Error('작성 화면을 다시 열어 주세요.');ctx.openModal('이미지 이모티콘',`<p class="section-note">모북이용으로 직접 만든 고정 규격 시연 이미지입니다.</p><div class="comm-emote-picker">${Object.keys(C.EMOTES).map(id=>cb('choose-emote',`${emoteImage(id)}<span>${esc(C.EMOTES[id].name)}</span>`,`data-destination="${destination}" data-emote="${id}"`,'comm-emote-option')).join('')}</div><p id="community-form-error" role="alert" class="form-error"></p>`,'community-emotes');}
  async function upload(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>P.inputBytes)throw Error('PNG·JPEG·WebP 형식의 2MB 이하 이미지를 선택해 주세요.');const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('이미지를 읽지 못했습니다.'));reader.readAsDataURL(file);});const image=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('올바른 이미지 파일이 아닙니다.'));image.src=raw;});if(image.naturalWidth*image.naturalHeight>24000000)throw Error('시연에서는 너무 큰 해상도의 이미지를 처리할 수 없습니다.');const ratio=Math.min(1,P.maxDimension/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(image.naturalHeight*ratio));const drawing=canvas.getContext('2d');if(!drawing)throw Error('이미지를 준비할 수 없습니다. 다른 이미지를 선택해 주세요.');drawing.drawImage(image,0,0,canvas.width,canvas.height);const dataUrl=canvas.toDataURL('image/png');if(dataUrl.length>P.imageDataChars)throw Error('변환한 이미지가 시연 저장 크기를 초과했습니다. 더 작은 이미지를 선택해 주세요.');return {id:'image-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),kind:'upload',dataUrl,width:canvas.width,height:canvas.height,name:file.name.slice(0,120)};}
  document.addEventListener('click',event=>{const el=event.target.closest('[data-community-action]');if(!el||el.disabled)return;syncSession();try{const action=el.dataset.communityAction;if(action==='board')ctx.go(boardRoute(el.dataset.board));else if(action==='post')ctx.go(postRoute(el.dataset.post));else if(action==='home-tab'){homeTab=el.dataset.tab;ctx.render();}else if(action==='head'){postHead=el.dataset.head;$('#community-board-results').innerHTML=boardResults(el.dataset.board);}else if(action==='favorite'){if(ctx.ensureUser()){store.toggleFavorite(el.dataset.board,ctx.getUser().id);ctx.render();}}else if(action==='compose'){if(ctx.ensureUser()){if(!editor)editor=store.draft()||store.newDraft(el.dataset.board);ctx.go('community-write?board='+encodeURIComponent(el.dataset.board));}}else if(action==='save-draft'){if(pendingUpload)throw Error('이미지 준비가 끝난 뒤 저장해 주세요.');readEditor();store.saveDraft(editor,ctx.getUser()?.id);$('#community-save-status').textContent='초안을 저장했어요. 다시 열어도 이어 쓸 수 있습니다.';}else if(action==='emotes'){if(ctx.ensureUser())picker(el.dataset.destination);}else if(action==='choose-emote'){const destination=el.dataset.destination,target=destination==='post'?editor:commentState(store.post(decodeURIComponent(ctx.route().parts[1]))),max=destination==='post'?P.postEmotes:P.commentEmotes;if(!Object.hasOwn(C.EMOTES,el.dataset.emote))throw Error('허용된 이미지 이모티콘을 선택해 주세요.');if(target.emotes.length>=max)throw Error(`시연에서는 이미지 이모티콘을 ${max}개까지 선택할 수 있어요.`);target.emotes.push(el.dataset.emote);ctx.closeModal(false);ctx.render();}else if(action==='remove-emote'){readEditor();const target=el.dataset.destination==='post'?editor:commentState(store.post(decodeURIComponent(ctx.route().parts[1])));target.emotes.splice(Number(el.dataset.index),1);ctx.render();}else if(action==='representative'){readEditor();editor.representativeId=el.dataset.image;ctx.render();}else if(action==='remove-image'){readEditor();editor.images=editor.images.filter(image=>image.id!==el.dataset.image);if(!editor.images.some(image=>image.id===editor.representativeId))editor.representativeId=editor.images[0]?.id||null;ctx.render();}else if(action==='ask-reveal'){if(!ctx.ensureUser())return;ctx.openModal('스포일러 내용을 열까요?',`<p>${esc(byWork(el.dataset.work)?.title||'연결 작품')} · ${esc(scopeLabel(el.dataset.work,Number(el.dataset.scope)))} 내용이 포함되어 있습니다.</p><form data-community-form="reveal" data-owner="${esc(ctx.getUser().id)}" data-kind="${el.dataset.kind}" data-item="${esc(el.dataset.item)}"><label class="comm-consent"><input name="confirmed" type="checkbox" required>이 내용의 스포일러를 확인하고 열겠습니다.</label><p class="section-note">이 글 또는 댓글에만 적용합니다. 독서 진도나 설정집 범위는 바꾸지 않아요.</p><p id="community-form-error" role="alert" class="form-error"></p><button class="primary" type="submit">확인 후 열기</button></form>`,'community-reveal');}}catch(e){error(e);}});
  document.addEventListener('input',event=>{if(event.target.id==='community-work-query'){workQuery=event.target.value;$('#community-work-results').innerHTML=workResults();}else if(event.target.id==='community-post-query'){postQuery=event.target.value;$('#community-board-results').innerHTML=boardResults(activeBoard);}else if(event.target.closest('[data-community-form="post"]'))readEditor();else if(event.target.id==='community-comment-body'){const post=store.post(decodeURIComponent(ctx.route().parts[1]));commentState(post).body=event.target.value;}});
  document.addEventListener('change',async event=>{try{if(event.target.id==='community-compose-board'){readEditor();const board=byBoard(event.target.value);editor.boardId=board.id;editor.head=board.heads[0];editor.linkedWorkId=board.workId||(board.type==='promotion'?store.works()[0]?.id:'')||'';editor.scope=0;ctx.render();}else if(event.target.id==='community-linked-work'){readEditor();editor.scope=0;ctx.render();}else if(event.target.id==='community-comment-scope'){commentState(store.post(decodeURIComponent(ctx.route().parts[1]))).scope=Number(event.target.value);}else if(event.target.id==='community-file'){readEditor();const current=editor,files=[...event.target.files];if(pendingUpload)throw Error('이미지를 준비하고 있어요. 잠시 뒤 다시 선택해 주세요.');if(current.images.length+files.length>P.maxImages)throw Error('시연에서는 본문 이미지 3장까지 사용할 수 있어요.');const token={};pendingUpload=token;$('#community-save-status').textContent='이미지를 준비하고 있어요.';try{const values=[];for(const file of files)values.push(await upload(file));if(pendingUpload!==token||editor!==current||ctx.getUser()?.id!==current.ownerId||ctx.route().parts[0]!=='community-write')return;if(current.images.length+values.length>P.maxImages)throw Error('시연에서는 본문 이미지 3장까지 사용할 수 있어요.');current.images.push(...values);if(!current.representativeId)current.representativeId=current.images[0]?.id||null;ctx.render();}finally{if(pendingUpload===token){pendingUpload=null;const status=$('#community-save-status');if(status)status.textContent='';}}}}catch(e){error(e);}});
  document.addEventListener('submit',event=>{const form=event.target;if(!form.matches('[data-community-form]'))return;event.preventDefault();try{if(!form.dataset.owner||form.dataset.owner!==ctx.getUser()?.id)throw Error('계정이 변경되었습니다. 작성 화면을 다시 열어 주세요.');if(form.dataset.communityForm==='post'){if(pendingUpload)throw Error('이미지 준비가 끝난 뒤 게시해 주세요.');readEditor();const id=store.publish(editor,form.dataset.owner);editor=null;ctx.go(postRoute(id));ctx.toast('커뮤니티에 글을 게시했어요.');}else if(form.dataset.communityForm==='comment'){const post=store.post(form.dataset.post),draft=commentState(post);draft.body=form.elements.body.value;store.addComment(post.id,{body:draft.body,emotes:draft.emotes,scope:draft.scope},form.dataset.owner);commentDrafts.delete(form.dataset.owner+':'+post.id);ctx.render();ctx.toast('댓글을 등록했어요.');}else if(form.dataset.communityForm==='reveal'){store.reveal(form.dataset.kind,form.dataset.item,form.elements.confirmed.checked,form.dataset.owner);ctx.closeModal(false);ctx.render();}}catch(e){error(e);}});
  return {syncSession,home,handles:page=>['community','community-workboards','community-board','community-post','community-write'].includes(page),render(route){syncSession();try{const [page,id]=route.parts;if(page==='community')return home();if(page==='community-workboards')return workBoards();if(page==='community-board')return boardPage(decodeURIComponent(id||''));if(page==='community-post')return postPage(decodeURIComponent(id||''));if(page==='community-write')return composer(route.params.get('board')||'');}catch(e){return shell(`${ctx.backHead('커뮤니티','community')}<div class="comm-empty"><h2>화면을 불러오지 못했어요</h2><p>${esc(e.message)}</p>${cb('home-tab','다시 불러오기','data-tab="work"','primary')}</div>`);}}};
 }};
})(typeof globalThis!=='undefined'?globalThis:this);
